  &lt;p class=&quot;MsoListParagraphCxSpMiddle&quot; style=&quot;margin-left:0.25in;text-indent:-0.25in;&quot;&gt;&lt;span style=&quot;font-size:10pt;font-family:Symbol;&quot;&gt;·&lt;span style=&quot;font-size:7pt;line-height:normal;font-family:&#039;Times New Roman&#039;;&quot;&gt;        
  &lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-size:10pt;font-family:Arial, sans-serif;color:#000000;&quot;&gt;Promote a
