  &lt;p class=&quot;MsoNormal&quot; style=&quot;margin-left:0.5in;text-indent:-0.25in;&quot;&gt;&lt;span class=&quot;UserInputTextChar&quot;&gt;&lt;span style=&quot;font-size:11pt;font-family:Wingdings;&quot;&gt;§&lt;span style=&quot;font-size:7pt;line-height:normal;font-family:&#039;Times New Roman&#039;;&quot;&gt;  &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;UserInputTextChar&quot;&gt;&lt;span style=&quot;font-size:11pt;font-family:Calibri, sans-serif;&quot;&gt;Lead the design and implementation of scalable and efficient data
  architecture solutions using GCP technologies such as BigQuery, Cloud
  Dataflow, Cloud Spanner, Pub/Sub, and Google Cloud Storage.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;/p&gt;
  &lt;p class=&quot;MsoNormal&quot; style=&quot;margin-left:0.5in;text-indent:-0.25in;&quot;&gt;&lt;span class=&quot;UserInputTextChar&quot;&gt;&lt;span style=&quot;font-size:11pt;font-family:Wingdings;&quot;&gt;§&lt;span style=&quot;font-size:7pt;line-height:normal;font-family:&#039;Times New Roman&#039;;&quot;&gt;  &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;UserInputTextChar&quot;&gt;&lt;span style=&quot;font-size:11pt;font-family:Calibri, sans-serif;&quot;&gt;Architect and manage data lakes and data warehouses with an emphasis
  on performance, scalability, and cost-efficiency.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;/p&gt;
  &lt;p class=&quot;MsoNormal&quot; style=&quot;margin-left:0.5in;text-indent:-0.25in;&quot;&gt;&lt;span style=&quot;font-size:11pt;font-family:Wingdings;&quot;&gt;§&lt;span style=&quot;font-size:7pt;line-height:normal;font-family:&#039;Times New Roman&#039;;&quot;&gt; 
  &lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-size:11pt;font-family:Calibri, sans-serif;color:#000000;&quot;&gt;Deep
